head.script:
scwin.trigger1_onclick = function(e) {
	comLib.fn_test("Tetfcewfwf");
};
scwin.onpageload = function() {
	window.comLib = {}; //This is WebSquare JavaScript Marker. Do not remove this line.
	comLib.fn_test = function(a) {
		comLib.fn_F_TEST(a);
	};
	comLib.fn_F_TEST = function(a) {
		window.rowJSON = {
			"addr": "서울시",
			"name": "손예진",
			"rowStatus": "R"
		};
		window.dataObj = {
			type: "json", // 데이터 타입. "xml","string","json","array"
			data: rowJSON, // 전달 데이터 객체.
			name: "paramTest" // 변수명. popup에서 $w.getParameter( "paramTest" )로 깨내올 수 있다.
		};
		window.options = {
			id: "popup1",
			type: "wframePopup",
			width: 700 + "px",
			height: 400 + "px",
			top: 100 + "px",
			left: 100 + "px",
			popupName: "Test111",
			modal: true,
			style: "",
			resizable: true,
			status: false,
			menubar: false,
			scrollbars: false,
			title: false,
			useMaximize: true,
			dataObject: dataObj
		};
		$p.openPopup("/sample/common_link/p_wframeOpup_getparameter_WEFF-599_(WSQ-3961)_main_sub.xml", options);
	};
}
